import{_ as a,o as d,c as i,a0 as e}from"./chunks/framework.jwovEGr5.js";const g=JSON.parse('{"title":"리눅스 시스템의 이해","description":"","frontmatter":{},"headers":[],"relativePath":"outta-space/project/리눅스-실무의-이해-리눅스-시스템의-이해.md","filePath":"outta-space/project/리눅스-실무의-이해-리눅스-시스템의-이해.md"}'),l={name:"outta-space/project/리눅스-실무의-이해-리눅스-시스템의-이해.md"};function r(h,t,s,n,o,c){return d(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="리눅스-시스템의-이해" tabindex="-1">리눅스 시스템의 이해 <a class="header-anchor" href="#리눅스-시스템의-이해" aria-label="Permalink to &quot;리눅스 시스템의 이해&quot;">​</a></h1><h2 id="리눅스와-하드웨어" tabindex="-1">리눅스와 하드웨어 <a class="header-anchor" href="#리눅스와-하드웨어" aria-label="Permalink to &quot;리눅스와 하드웨어&quot;">​</a></h2><h3 id="컴퓨터의-구성-요소" tabindex="-1">컴퓨터의 구성 요소 <a class="header-anchor" href="#컴퓨터의-구성-요소" aria-label="Permalink to &quot;컴퓨터의 구성 요소&quot;">​</a></h3><table tabindex="0"><thead><tr><th>구성 요소</th><th>역할</th><th>예시</th></tr></thead><tbody><tr><td>CPU</td><td>명령 해석·연산과 시스템 제어</td><td>ALU, 제어장치, 레지스터</td></tr><tr><td>주기억장치</td><td>실행 중인 명령과 데이터 저장</td><td>RAM, ROM</td></tr><tr><td>입력장치</td><td>외부 데이터를 컴퓨터에 전달</td><td>키보드, 마우스, OCR, OMR</td></tr><tr><td>출력장치</td><td>처리 결과를 사용자에게 전달</td><td>모니터, 프린터, HMD</td></tr><tr><td>보조기억장치</td><td>대용량 데이터를 비휘발성으로 저장</td><td>HDD, SSD, 광학 디스크</td></tr></tbody></table><h4 id="cpu" tabindex="-1">CPU <a class="header-anchor" href="#cpu" aria-label="Permalink to &quot;CPU&quot;">​</a></h4><ul><li>레지스터: CPU 내부의 가장 빠르고 작은 임시 저장장치</li><li>ALU(Arithmetic Logic Unit): 산술·논리·비교 연산</li><li>제어장치(Control Unit): 명령을 해석하고 각 장치의 동작을 제어</li></ul><h4 id="주기억장치" tabindex="-1">주기억장치 <a class="header-anchor" href="#주기억장치" aria-label="Permalink to &quot;주기억장치&quot;">​</a></h4><table tabindex="0"><thead><tr><th>종류</th><th>특성</th><th>주요 용도</th></tr></thead><tbody><tr><td>DRAM</td><td>집적도가 높고 비교적 느림, 주기적인 재충전 필요</td><td>주 메모리</td></tr><tr><td>SRAM</td><td>빠르고 비싸며 집적도가 낮음, 재충전 불필요</td><td>CPU 캐시</td></tr><tr><td>ROM</td><td>전원이 꺼져도 내용 유지</td><td>펌웨어 저장</td></tr></tbody></table><p>ROM 계열은 기록 방식에 따라 Mask ROM, PROM, EPROM, EEPROM·Flash 등으로 나뉜다. 현대 PC의 UEFI 펌웨어는 일반적으로 플래시 메모리에 저장된다.</p><h4 id="입력장치-구분" tabindex="-1">입력장치 구분 <a class="header-anchor" href="#입력장치-구분" aria-label="Permalink to &quot;입력장치 구분&quot;">​</a></h4><ul><li>OMR(Optical Mark Reader): 답안지처럼 표시된 마크 판독</li><li>OCR(Optical Character Recognition): 인쇄·필기 문자를 문자 데이터로 변환</li><li>MICR(Magnetic Ink Character Recognition): 자기 잉크로 인쇄된 문자 판독</li></ul><h3 id="linux-설치-전-하드웨어-확인" tabindex="-1">Linux 설치 전 하드웨어 확인 <a class="header-anchor" href="#linux-설치-전-하드웨어-확인" aria-label="Permalink to &quot;Linux 설치 전 하드웨어 확인&quot;">​</a></h3><h4 id="cpu-1" tabindex="-1">CPU <a class="header-anchor" href="#cpu-1" aria-label="Permalink to &quot;CPU&quot;">​</a></h4><ul><li>배포판이 CPU 아키텍처를 지원하는지 확인한다.</li><li>대표 아키텍처: x86-64, ARM64, RISC-V, PowerPC 등</li><li>가상 머신을 사용할 경우 Intel VT-x 또는 AMD-V 같은 하드웨어 가상화 기능도 확인한다.</li><li>병렬성(Parallelism)은 여러 코어·프로세서에서 실제 계산을 동시에 수행하는 것이고, 동시성(Concurrency)은 여러 작업의 진행이 시간상 겹치는 개념이다.</li></ul><h4 id="메인보드와-펌웨어" tabindex="-1">메인보드와 펌웨어 <a class="header-anchor" href="#메인보드와-펌웨어" aria-label="Permalink to &quot;메인보드와 펌웨어&quot;">​</a></h4><ul><li>칩셋, 저장장치 컨트롤러와 네트워크 장치 지원 여부 확인</li><li>설치·부팅 문제가 있으면 UEFI 설정과 펌웨어 업데이트 확인</li><li>Secure Boot, 저장장치 모드와 부팅 순서 확인</li></ul><h4 id="메모리" tabindex="-1">메모리 <a class="header-anchor" href="#메모리" aria-label="Permalink to &quot;메모리&quot;">​</a></h4><ul><li>배포판과 실행할 서비스의 최소·권장 용량 확인</li><li>64비트 환경에서는 32비트보다 넓은 주소 공간을 사용할 수 있다.</li><li>지원 가능한 최대 메모리는 CPU뿐 아니라 메인보드와 배포판·커널 설정에도 좌우된다.</li><li>swap은 메모리 부족을 보완하지만 RAM을 대체할 만큼 빠르지는 않다.</li></ul><h4 id="저장장치" tabindex="-1">저장장치 <a class="header-anchor" href="#저장장치" aria-label="Permalink to &quot;저장장치&quot;">​</a></h4><p>Linux에서는 저장장치도 장치 파일로 표현한다.</p><table tabindex="0"><thead><tr><th>장치</th><th>일반적인 이름 예</th></tr></thead><tbody><tr><td>SATA·SAS·SCSI·USB 저장장치</td><td><code>/dev/sda</code>, <code>/dev/sdb</code></td></tr><tr><td>NVMe SSD</td><td><code>/dev/nvme0n1</code></td></tr><tr><td>오래된 IDE 장치</td><td><code>/dev/hda</code></td></tr></tbody></table><p>장치명은 검색 순서에 따라 바뀔 수 있으므로 영구 설정에는 UUID나 <code>/dev/disk/by-*</code> 링크를 사용하는 편이 안전하다.</p><h4 id="그래픽·네트워크·입력장치" tabindex="-1">그래픽·네트워크·입력장치 <a class="header-anchor" href="#그래픽·네트워크·입력장치" aria-label="Permalink to &quot;그래픽·네트워크·입력장치&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lspci</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # PCI 장치 확인</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lspci</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Ei</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vga|3d|display&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lspci</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ethernet</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsusb</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # USB 장치 확인</span></span></code></pre></div><ul><li>일반적인 장치는 커널 내장 드라이버로 동작한다.</li><li>최신 GPU, Wi-Fi와 특수 장치는 별도 펌웨어나 제조사 드라이버가 필요할 수 있다.</li><li>네트워크 설치 전 IP 주소, 프리픽스·넷마스크, 게이트웨이와 DNS 정보를 확인한다.</li></ul><h2 id="raid" tabindex="-1">RAID <a class="header-anchor" href="#raid" aria-label="Permalink to &quot;RAID&quot;">​</a></h2><p>RAID(Redundant Array of Independent Disks)는 여러 디스크를 하나의 논리 장치로 묶어 성능, 용량 또는 장애 허용성을 높이는 기술이다.</p><ul><li>Striping: 데이터를 여러 디스크에 나누어 기록</li><li>Mirroring: 같은 데이터를 여러 디스크에 복제</li><li>Parity: 손실된 데이터를 계산해 복구하기 위한 정보</li></ul><p>RAID는 백업이 아니다. 실수로 삭제하거나 손상된 데이터도 함께 반영될 수 있으므로 별도 백업이 필요하다.</p><h3 id="raid-레벨-비교" tabindex="-1">RAID 레벨 비교 <a class="header-anchor" href="#raid-레벨-비교" aria-label="Permalink to &quot;RAID 레벨 비교&quot;">​</a></h3><p><code>N</code>은 같은 크기의 디스크 수, <code>S</code>는 가장 작은 디스크의 용량이다.</p><table tabindex="0"><thead><tr><th>레벨</th><th>구성</th><th style="text-align:right;">최소 디스크</th><th style="text-align:right;">사용 가능 용량</th><th style="text-align:right;">장애 허용</th><th>핵심</th></tr></thead><tbody><tr><td>RAID 0</td><td>Striping</td><td style="text-align:right;">2</td><td style="text-align:right;"><code>N × S</code></td><td style="text-align:right;">0개</td><td>빠르지만 디스크 하나만 고장 나도 전체 손실</td></tr><tr><td>RAID 1</td><td>Mirroring</td><td style="text-align:right;">2</td><td style="text-align:right;">보통 <code>S</code></td><td style="text-align:right;">미러당 1개</td><td>안정적이지만 2개 구성의 공간 효율 50%</td></tr><tr><td>RAID 2</td><td>비트 Striping + Hamming ECC</td><td style="text-align:right;">다수</td><td style="text-align:right;">구성에 따라 다름</td><td style="text-align:right;">구성에 따라 다름</td><td>현재 거의 사용하지 않음</td></tr><tr><td>RAID 3</td><td>바이트 Striping + 전용 Parity</td><td style="text-align:right;">3</td><td style="text-align:right;"><code>(N-1) × S</code></td><td style="text-align:right;">1개</td><td>전용 패리티 디스크 사용, 거의 사용하지 않음</td></tr><tr><td>RAID 4</td><td>블록 Striping + 전용 Parity</td><td style="text-align:right;">3</td><td style="text-align:right;"><code>(N-1) × S</code></td><td style="text-align:right;">1개</td><td>패리티 디스크의 쓰기 병목</td></tr><tr><td>RAID 5</td><td>블록 Striping + 분산 Parity</td><td style="text-align:right;">3</td><td style="text-align:right;"><code>(N-1) × S</code></td><td style="text-align:right;">1개</td><td>성능·용량·안정성의 균형</td></tr><tr><td>RAID 6</td><td>블록 Striping + 이중 분산 Parity</td><td style="text-align:right;">4</td><td style="text-align:right;"><code>(N-2) × S</code></td><td style="text-align:right;">2개</td><td>RAID 5보다 안전하지만 쓰기 비용 증가</td></tr><tr><td>RAID 0+1</td><td>Stripe 묶음을 Mirror</td><td style="text-align:right;">4</td><td style="text-align:right;"><code>N/2 × S</code></td><td style="text-align:right;">구성에 따라 다름</td><td>한 Stripe 묶음 장애 후 허용성 감소</td></tr><tr><td>RAID 1+0</td><td>Mirror 묶음을 Stripe</td><td style="text-align:right;">4</td><td style="text-align:right;"><code>N/2 × S</code></td><td style="text-align:right;">미러별 1개 가능</td><td>RAID 0+1보다 일반적으로 복구와 장애 허용성이 좋음</td></tr></tbody></table><p>RAID 10은 RAID 1+0을 뜻한다. 교재에 나오는 RAID 5+3 같은 표기는 표준 RAID 레벨이라기보다 여러 RAID 구성을 중첩한 특수 구성으로 이해한다.</p><h3 id="raid-선택-기준" tabindex="-1">RAID 선택 기준 <a class="header-anchor" href="#raid-선택-기준" aria-label="Permalink to &quot;RAID 선택 기준&quot;">​</a></h3><ul><li>최대 성능, 데이터 보호 불필요: RAID 0</li><li>단순한 이중화: RAID 1</li><li>용량 효율과 1개 디스크 장애 허용: RAID 5</li><li>대용량 배열에서 2개 디스크 장애 허용: RAID 6</li><li>높은 성능과 안정성: RAID 10</li></ul><p>패리티는 장애 복구 정보이며 백업 복사본은 아니다. RAID 5·6은 고장 난 디스크를 교체한 뒤 재구축하는 동안 성능이 낮아지고 추가 장애 위험이 커질 수 있다.</p><h2 id="디스크-인터페이스" tabindex="-1">디스크 인터페이스 <a class="header-anchor" href="#디스크-인터페이스" aria-label="Permalink to &quot;디스크 인터페이스&quot;">​</a></h2><table tabindex="0"><thead><tr><th>인터페이스</th><th>전송 방식</th><th>주요 환경</th><th>특징</th></tr></thead><tbody><tr><td>IDE·PATA</td><td>병렬</td><td>구형 PC</td><td>40핀 리본 케이블, 현재 거의 사용하지 않음</td></tr><tr><td>SATA</td><td>직렬</td><td>PC, 일반 서버</td><td>보급형 저장장치의 대표 규격</td></tr><tr><td>Parallel SCSI</td><td>병렬</td><td>구형 서버·워크스테이션</td><td>안정성과 장치 확장성, 현재는 감소</td></tr><tr><td>SAS</td><td>직렬</td><td>서버·데이터센터</td><td>SCSI 명령 체계, 고성능·신뢰성·확장성</td></tr></tbody></table><h3 id="sata-세대별-링크-속도" tabindex="-1">SATA 세대별 링크 속도 <a class="header-anchor" href="#sata-세대별-링크-속도" aria-label="Permalink to &quot;SATA 세대별 링크 속도&quot;">​</a></h3><table tabindex="0"><thead><tr><th>세대</th><th style="text-align:right;">이론상 링크 속도</th><th>흔히 부르는 이름</th></tr></thead><tbody><tr><td>SATA 1</td><td style="text-align:right;">1.5 Gbit/s</td><td>SATA 150</td></tr><tr><td>SATA 2</td><td style="text-align:right;">3 Gbit/s</td><td>SATA 300</td></tr><tr><td>SATA 3</td><td style="text-align:right;">6 Gbit/s</td><td>SATA 600</td></tr></tbody></table><p>링크 속도는 인코딩 오버헤드를 포함하므로 실제 데이터 전송률은 표기값보다 낮다.</p><h3 id="sata와-sas" tabindex="-1">SATA와 SAS <a class="header-anchor" href="#sata와-sas" aria-label="Permalink to &quot;SATA와 SAS&quot;">​</a></h3><ul><li>SATA: 가격과 범용성을 중시하는 PC·일반 서버용</li><li>SAS: 이중 포트, 확장성, 신뢰성과 연속 운용을 중시하는 기업용</li><li>SAS 컨트롤러는 보통 SATA 드라이브도 연결할 수 있지만, SATA 컨트롤러에는 SAS 드라이브를 연결할 수 없다.</li></ul><p>NVMe는 PCI Express 위에서 동작하며 SATA·SAS와 다른 현대적인 SSD 인터페이스다.</p><h2 id="시험-핵심" tabindex="-1">시험 핵심 <a class="header-anchor" href="#시험-핵심" aria-label="Permalink to &quot;시험 핵심&quot;">​</a></h2><ul><li>CPU 구성: 레지스터, ALU, 제어장치</li><li>DRAM은 주 메모리, SRAM은 캐시, ROM·Flash는 비휘발성 펌웨어 저장</li><li>OMR은 마크, OCR은 문자, MICR은 자기 잉크 문자 판독</li><li>SATA·SCSI 계열은 보통 <code>/dev/sdX</code>, NVMe는 <code>/dev/nvme0n1</code></li><li>RAID 0은 성능만, RAID 1은 Mirroring, RAID 5는 분산 Parity 1개, RAID 6은 Parity 2개</li><li>RAID 10은 Mirror 후 Stripe이며 RAID 0+1보다 일반적으로 장애 대응에 유리</li><li>PATA·SCSI는 병렬, SATA·SAS는 직렬</li></ul>`,46)])])}const A=a(l,[["render",r]]);export{g as __pageData,A as default};
